const M = 26;

function gcd(a, b) {
  while (b !== 0) {
    [a, b] = [b, a % b];
  }
  return a;
}

function modInverse(a, m) {
  let [old_r, r] = [a, m];
  let [old_s, s] = [1, 0];
  while (r !== 0) {
    const q = Math.floor(old_r / r);
    [old_r, r] = [r, old_r - q * r];
    [old_s, s] = [s, old_s - q * s];
  }
  return ((old_s % m) + m) % m;
}

function validateKey(a) {
  if (gcd(a, M) !== 1) {
    throw new Error('Error: keyA and alphabet size must be coprime.');
  }
}

export const encode = (phrase, key) => {
  const { a, b } = key;
  validateKey(a);

  const cleaned = phrase.toLowerCase().replace(/[^a-z0-9]/g, '');
  let result = '';

  for (const ch of cleaned) {
    if (ch >= '0' && ch <= '9') {
      result += ch;
    } else {
      const i = ch.charCodeAt(0) - 97;
      const encoded = (a * i + b) % M;
      result += String.fromCharCode(encoded + 97);
    }
  }

  // Group into blocks of 5
  const groups = [];
  for (let i = 0; i < result.length; i += 5) {
    groups.push(result.slice(i, i + 5));
  }
  return groups.join(' ');
};

