  const { a, b } = key;
  validateKey(a);

  const mmi = modInverse(a, M);
  const cleaned = phrase.replace(/\s/g, '');
  let result = '';

  for (const ch of cleaned) {
    if (ch >= '0' && ch <= '9') {
      result += ch;
    } else {
      const y = ch.charCodeAt(0) - 97;
      const decoded = ((mmi * ((y - b) % M + M)) % M);
      result += String.fromCharCode(decoded + 97);
    }
  }

  return result;
