export const solve = (puzzle) => {
  // Split the puzzle into left and right sides
  const [left, right] = puzzle.split('=').map(s => s.trim());
  if (!left || !right) {
    throw new Error('Invalid puzzle format');
  }

  // Split left side by '+' to get words
  const leftWords = left.split(/\s*\+\s*/).map(w => w.trim());
  const rightWord = right.trim();

  // Collect all unique letters and leading letters
  const letters = new Set();
  const leadingLetters = new Set();
  const allWords = [...leftWords, rightWord];
  for (const word of allWords) {
    for (const ch of word) {
      letters.add(ch);
    }
    if (word.length > 0) {
      leadingLetters.add(word[0]);
    }
  }

  const letterArray = Array.from(letters);
  const numLetters = letterArray.length;
  if (numLetters > 10) {
    return null; // impossible to assign distinct digits
  }

  // Prepare for backtracking
  const used = new Set();
  const assignment = {};

  const wordValue = (word) => {
    let val = 0;
    for (const ch of word) {
      val = val * 10 + assignment[ch];
    }
    return val;
  };

  const backtrack = (idx) => {
    if (idx === numLetters) {
      // All letters assigned, check equation
      const leftSum = leftWords.reduce((sum, w) => sum + wordValue(w), 0);
      const rightVal = wordValue(rightWord);
      return leftSum === rightVal;
    }

    const ch = letterArray[idx];
    for (let d = 0; d <= 9; d++) {
      if (used.has(d)) continue;
      if (d === 0 && leadingLetters.has(ch)) continue;

      assignment[ch] = d;
      used.add(d);
      if (backtrack(idx + 1)) {
        return true;
      }
      used.delete(d);
      // assignment[ch] will be overwritten later, no need to delete
    }
    return false;
  };

  if (backtrack(0)) {
    return assignment;
  }
  return null;
};

