export class Binary {
  constructor(binary) {
    this.binary = binary;
  }

  toDecimal() {
    const str = this.binary;

    // Check if input is valid binary string
    if (typeof str !== 'string' || !/^[01]+$/.test(str)) {
      return 0;
    }

    let result = 0;
    for (let i = 0; i < str.length; i++) {
      const digit = str[str.length - 1 - i];
      if (digit === '1') {
        result += Math.pow(2, i);
      }
    }
    return result;
  }
}

