export const cost = (books) => {
  // Count occurrences of each book (1-5)
  const counts = Array(5).fill(0);
  for (const book of books) {
    counts[book - 1]++;
  }

  // Memoization cache
  const memo = new Map();

  // Helper function to calculate optimal price for current counts
  const calculatePrice = (state) => {
    // Create cache key from state
    const key = state.join(',');
    if (memo.has(key)) {
      return memo.get(key);
    }

    // If all counts are zero, return 0
    if (state.every(count => count === 0)) {
      return 0;
    }

    let minPrice = Infinity;

    // Try forming groups of different sizes (1-5)
    for (let groupSize = 5; groupSize >= 1; groupSize--) {
      // Check if we have enough distinct books for this group size
      const availableBooks = state.filter(count => count > 0).length;
      if (availableBooks < groupSize) {
        continue;
      }

      // Create new state by taking one of each book in the group
      const newState = [...state];
      let booksTaken = 0;

      for (let i = 0; i < 5 && booksTaken < groupSize; i++) {
        if (newState[i] > 0) {
          newState[i]--;
          booksTaken++;
        }
      }

      // Calculate discount multiplier based on group size
      let discountMultiplier;
      switch (groupSize) {
        case 1:
          discountMultiplier = 1.0;
          break;
        case 2:
          discountMultiplier = 0.95;
          break;
        case 3:
          discountMultiplier = 0.90;
          break;
        case 4:
          discountMultiplier = 0.80;
          break;
        case 5:
          discountMultiplier = 0.75;
          break;
      }

      // Calculate price for this group (in cents)
      const groupPrice = Math.round(groupSize * 800 * discountMultiplier);

      // Recursively calculate price for remaining books
      const remainingPrice = calculatePrice(newState);
      const totalPrice = groupPrice + remainingPrice;

      if (totalPrice < minPrice) {
        minPrice = totalPrice;
      }
    }

    memo.set(key, minPrice);
    return minPrice;
  };

  return calculatePrice(counts);
};

