    'Omschrijving'.padEnd(25, ' ') +
    ' | ' +
    'Verandering'.padEnd(13, ' ')
  );
}

function formatEntry(entry, currency, locale) {
  const dateStr = formatDate(entry.date, locale);
  const descStr = truncateDescription(entry.description);
  const changeStr = formatChange(entry.change, currency, locale).padStart(13, ' ');
  return `${dateStr} | ${descStr} | ${changeStr}`;
}

function sortEntries(entries) {
  entries.sort(
