          if (largest === null || product > largest) {
            largest = product;
          }
        }
      }
    }

    if (smallest === null && largest === null) {
      return {
        smallest: { value: null, factors: [] },
        largest: { value: null, factors: [] }
      };
    }

    return {
      smallest: { value: smallest, factors: palindromeFactors.get(smallest) || [] },
      largest: { value: largest, factors: palindromeFactors.get(largest) || [] }
    };
  }
}

