      worker.on('exit', (code) => {
        if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
      });
    });
  });

  const results = await Promise.all(promises);
  const totalFrequencies = {};
  for (const freq of results) {
    for (const [letter, count] of Object.entries(freq)) {
