  let count = 0;

  for (let i1 = 0; i1 < rows; i1++) {
    for (let i2 = i1 + 1; i2 < rows; i2++) {
      for (let j1 = 0; j1 < cols; j1++) {
        for (let j2 = j1 + 1; j2 < cols; j2++) {
          // Check corners
          if (lines[i1][j1] !== '+' || 
              lines[i1][j2] !== '+' || 
              lines[i2][j1] !== '+' || 
              lines[i2][j2] !== '+') {
            continue;
          }

          // Check top edge
          let valid = true;
          for (let j = j1 + 1; j < j2; j++) {
            if (lines[i1][j] !== '-' && lines[i1][j] !== '+') {
              valid = false;
              break;
            }
          }
          if (!valid) continue;

          // Check bottom edge
          for (let j = j1 + 1; j < j2; j++) {
            if (lines[i2][j] !== '-' && lines[i2][j] !== '+') {
              valid = false;
              break;
            }
          }
          if (!valid) continue;

          // Check left edge
          for (let i = i1 + 1; i < i2; i++) {
