      numStr = value.toString();
    } else {
      numStr = value.toFixed(1);
      if (numStr.endsWith('.0')) {
        numStr = numStr.slice(0, -2);
      }
    }

    let prefix = prefixes[prefixIndex];
    if (value === 1) {
      prefix = prefix.replace(/s$/, '');
    }

    return `${numStr} ${prefix}`;
