      let users;
      if (queryString) {
        const params = new URLSearchParams(queryString);
        const names = params.get('users').split(',');
        users = this.db.users
          .filter(u => names.includes(u.name))
          .sort((a, b) => a.name.localeCompare(b.name));
      } else {
        users = [...this.db.users].sort((a, b) => a.name.localeCompare(b.name));
      }
      return { users };
    }
  }

  post(url, payload) {
    if (url === '/add') {
      const newUser = {
        name: payload.user,
        owes: {},
        owed_by: {},
        balance: 0,
      };
      this.db.users.push(newUser);
      return { name: newUser.name, owes: {}, owed_by: {}, balance: 0 };
    }

    if (url === '/iou') {
      const { lender, borrower, amount } = payload;
      const lenderUser = this.db.users.find(u => u.name === lender);
      const borrowerUser = this.db.users.find(u => u.name === borrower);

      // Calculate current net debt: positive means borrower owes lender
      let currentNet = 0;
      if (borrowerUser.owes[lender]) {
        currentNet += borrowerUser.owes[lender];
      }
      if (lenderUser.owes[borrower]) {
        currentNet -= lenderUser.owes[borrower];
      }

      const newNet = currentNet + amount;

      // Clear both directions
      delete lenderUser.owes[borrower];
      delete lenderUser.owed_by[borrower];
      delete borrowerUser.owes[lender];
      delete borrowerUser.owed_by[lender];

      if (newNet > 0) {
        borrowerUser.owes[lender] = Math.round(newNet * 100) / 100;
        lenderUser.owed_by[borrower] = Math.round(newNet * 100) / 100;
      } else if (newNet < 0) {
        lenderUser.owes[borrower] = Math.round((-newNet) * 100) / 100;
        borrowerUser.owed_by[lender] = Math.round((-newNet) * 100) / 100;
      }

      this.recalcBalance(lenderUser);
      this.recalcBalance(borrowerUser);

      return {
        users: [lenderUser, borrowerUser].sort((a, b) =>
          a.name.localeCompare(b.name)
        ),
      };
    }
  }

  recalcBalance(user) {
    const totalOwedBy = Object.values(user.owed_by).reduce((s, v) => s + v, 0);
    const totalOwes = Object.values(user.owes).reduce((s, v) => s + v, 0);
    user.balance = Math.round((totalOwedBy - totalOwes) * 100) / 100;
  }
}

