export const gamestate = (board) => {
  // Validate board structure
  if (board.length !== 3) {
    throw new Error('Invalid board: must have 3 rows');
  }
  for (const row of board) {
    if (row.length !== 3) {
      throw new Error('Invalid board: each row must have 3 characters');
    }
  }

  // Convert board to grid array
  const grid = board.map(row => row.split(''));

  // Count X's and O's
  let xCount = 0;
  let oCount = 0;
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      const cell = grid[i][j];
      if (cell === 'X') xCount++;
      else if (cell === 'O') oCount++;
      else if (cell !== ' ') {
        throw new Error('Invalid board: invalid character');
      }
    }
  }

  // Validate turn order
  if (!(xCount === oCount || xCount === oCount + 1)) {
    throw new Error('Invalid board: wrong turn order');
