  const teams = {};

  const lines = input.split('\n').filter(line => line.trim() !== '');

  for (const line of lines) {
    const [team1, team2, result] = line.split(';');

    if (!teams[team1]) {
      teams[team1] = { mp: 0, w: 0, d: 0, l: 0, p: 0 };
    }
    if (!teams[team2]) {
      teams[team2] = { mp: 0, w: 0, d: 0, l: 0, p: 0 };
    }

    teams[team1].mp++;
    teams[team2].mp++;

    switch (result) {
      case 'win':
        teams[team1].w++;
        teams[team1].p += 3;
        teams[team2].l++;
        break;
      case 'loss':
        teams[team2].w++;
        teams[team2].p += 3;
        teams[team1].l++;
        break;
      case 'draw':
        teams[team1].d++;
        teams[team1].p += 1;
        teams[team2].d++;
        teams[team2].p += 1;
        break;
    }
  }

  const teamEntries = Object.entries(teams);
  teamEntries.sort((a, b) => {
    if (b[1].p !== a[1].p) {
      return b[1].p - a[1].p;
    }
    return a[0].localeCompare(b[0]);
  });

