  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    // Check if it's a number (including negative)
    if (/^-?\d+$/.test(token)) {
      currentNum = parseInt(token, 10);

      // Apply any pending operation
      if (result === null) {
        result = currentNum;
      } else if (operator) {
        switch (operator) {
          case "plus":
            result += currentNum;
            break;
          case "minus":
            result -= currentNum;
            break;
          case "multiplied":
            result *= currentNum;
            break;
          case "divided":
            if (currentNum === 0) {
              throw new Error("Division by zero");
            }
            result = Math.trunc(result / currentNum);
