export class ZebraPuzzle {
  constructor() {
    this.solution = this.solve();
  }

  solve() {
    // All possible values for each category
    const colors = ['red', 'green', 'ivory', 'yellow', 'blue'];
    const nationalities = ['Englishman', 'Spaniard', 'Ukrainian', 'Norwegian', 'Japanese'];
    const pets = ['dog', 'snail', 'fox', 'horse', 'zebra'];
    const drinks = ['coffee', 'tea', 'milk', 'orange juice', 'water'];
    const hobbies = ['dancing', 'painting', 'reading', 'football', 'chess'];

    // Generate all permutations for each category
    const permutations = this.getPermutations(colors);
    const natPerms = this.getPermutations(nationalities);
    const petPerms = this.getPermutations(pets);
    const drinkPerms = this.getPermutations(drinks);
    const hobbyPerms = this.getPermutations(hobbies);

    // Try all combinations of permutations
    for (const colorPerm of permutations) {
      for (const natPerm of natPerms) {
        for (const petPerm of petPerms) {
          for (const drinkPerm of drinkPerms) {
            for (const hobbyPerm of hobbyPerms) {
              if (this.checkConstraints(colorPerm, natPerm, petPerm, drinkPerm, hobbyPerm)) {
                return {
                  color: colorPerm,
                  nationality: natPerm,
                  pet: petPerm,
                  drink: drinkPerm,
                  hobby: hobbyPerm
                };
              }
            }
          }
        }
      }
    }

    return null;
  }

  getPermutations(arr) {
    const result = [];

    const permute = (current, remaining) => {
      if (remaining.length === 0) {
        result.push([...current]);
        return;
      }

      for (let i = 0; i < remaining.length; i++) {
        const next = remaining[i];
        const newRemaining = [...remaining.slice(0, i), ...remaining.slice(i + 1)];
        permute([...current, next], newRemaining);
      }
    };

    permute([], arr);
    return result;
  }

  checkConstraints(color, nat, pet, drink, hobby) {
    // Helper function to find house index by attribute value
    const houseBy = (arr, val) => arr.indexOf(val);

    // Constraint 1: There are five houses - already satisfied by array length

    // Constraint 2: Englishman lives in red house
    if (houseBy(nat, 'Englishman') !== houseBy(color, 'red')) {
      return false;
    }

    // Constraint 3: Spaniard owns dog
    if (houseBy(nat, 'Spaniard') !== houseBy(pet, 'dog')) {
      return false;
    }

    // Constraint 4: Green house drinks coffee
    if (houseBy(color, 'green') !== houseBy(drink, 'coffee')) {
      return false;
    }

    // Constraint 5: Ukrainian drinks tea
    if (houseBy(nat, 'Ukrainian') !== houseBy(drink, 'tea')) {
      return false;
    }

    // Constraint 6: Green house is immediately to the right of ivory house
    const ivoryIndex = houseBy(color, 'ivory');
    const greenIndex = houseBy(color, 'green');
    if (greenIndex !== ivoryIndex + 1) {
      return false;
    }

    // Constraint 7: Snail owner likes dancing
    if (houseBy(pet, 'snail') !== houseBy(hobby, 'dancing')) {
      return false;
    }

    // Constraint 8: Yellow house is a painter
    if (houseBy(color, 'yellow') !== houseBy(hobby, 'painting')) {
      return false;
    }

    // Constraint 9: Middle house drinks milk (index 2)
    if (drink[2] !== 'milk') {
      return false;
    }

    // Constraint 10: Norwegian lives in first house (index 0)
    if (nat[0] !== 'Norwegian') {
      return false;
    }

    // Constraint 11: Reading lives next to fox
    const readingIndex = houseBy(hobby, 'reading');
    const foxIndex = houseBy(pet, 'fox');
    if (Math.abs(readingIndex - foxIndex) !== 1) {
      return false;
    }

    // Constraint 12: Painter's house is next to horse
    const painterIndex = houseBy(hobby, 'painting');
    const horseIndex = houseBy(pet, 'horse');
    if (Math.abs(painterIndex - horseIndex) !== 1) {
