      return false;
    }

    // Constraint 15: Norwegian lives next to blue house
    const norwegianIndex = houseBy(nat, 'Norwegian');
    const blueIndex = houseBy(color, 'blue');
    if (Math.abs(norwegianIndex - blueIndex) !== 1) {
      return false;
    }

    return true;
  }

