    const waterIndex = this.solution.drink.indexOf('water');
    return this.solution.nationality[waterIndex];
  }

  zebraOwner() {
    const zebraIndex = this.solution.pet.indexOf('zebra');
    return this.solution.nationality[zebraIndex];
  }
}

