export class Zipper {
  constructor(tree, trail) {
    this._tree = tree;
    this._trail = trail;
  }

  static fromTree(tree) {
    if (!tree) return null;
    return new Zipper(tree, []);
  }

  toTree() {
    let current = this;
    while (current._trail.length > 0) {
      current = current.up();
    }
    return current._tree;
  }

  value() {
    return this._tree.value;
  }

  left() {
    if (!this._tree.left) return null;
    const crumb = { tag: 'left', value: this._tree.value, right: this._tree.right };
    return new Zipper(this._tree.left, [crumb, ...this._trail]);
  }

  right() {
    if (!this._tree.right) return null;
    const crumb = { tag: 'right', value: this._tree.value, left: this._tree.left };
    return new Zipper(this._tree.right, [crumb, ...this._trail]);
  }

  up() {
    if (this._trail.length === 0) return null;
    const [crumb, ...rest] = this._trail;
    let tree;
    if (crumb.tag === 'left') {
      tree = { value: crumb.value, left: this._tree, right: crumb.right };
    } else {
      tree = { value: crumb.value, left: crumb.left, right: this._tree };
    }
    return new Zipper(tree, rest);
  }

  setValue(value) {
    return new Zipper(
      { value, left: this._tree.left, right: this._tree.right },
      this._trail
    );
  }

  setLeft(tree) {
    return new Zipper(
      { value: this._tree.value, left: tree, right: this._tree.right },
      this._trail
    );
  }

  setRight(tree) {
    return new Zipper(
      { value: this._tree.value, left: this._tree.left, right: tree },
      this._trail
    );
  }
}
